function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
var LEVELS={
  '单元测试':{desc:'验证函数 / 方法级逻辑与边界条件', sample:function(f){return '验证「'+f+'」各分支与边界输入返回符合预期';}},
  '集成测试':{desc:'验证模块间接口、数据流与依赖协作', sample:function(f){return '验证「'+f+'」与上下游模块的接口契约，检查异常透传';}},
  '端到端测试':{desc:'验证关键用户路径的端到端行为', sample:function(f){return '从入口到落库走通「'+f+'」主路径与典型异常路径';}},
  '性能测试':{desc:'验证吞吐、延迟与稳定性指标', sample:function(f){return '对「'+f+'」做负载 / 压力测试，记录 P95 延迟与错误率';}},
  '安全测试':{desc:'验证鉴权、注入与越权风险', sample:function(f){return '对「'+f+'」做越权 / 注入 / 敏感数据泄露扫描';}}
};
function buildTestPlan(o){
  o=o||{};
  var feature=String(o.feature||'').trim()||'（待填写功能名）';
  var scope=splitLines(o.scope);
  if(!scope.length) scope=['（待补充测试范围）'];
  var levels=splitLines(o.levels);
  if(!levels.length) levels=['单元测试','集成测试','端到端测试'];
  var env=String(o.env||'').trim()||'测试环境（含依赖服务的稳定版本）';
  var lines=[], cases=0;
  lines.push('# 测试计划：'+feature);
  lines.push('');
  lines.push('## 一、测试目标');
  lines.push('- 验证「'+feature+'」满足需求与验收标准，覆盖功能、边界与非功能质量属性');
  lines.push('');
  lines.push('## 二、测试范围');
  lines.push('- 范围内：'); scope.forEach(function(s){ lines.push('  - '+s); });
  lines.push('- 范围外：生产数据迁移、第三方内部实现细节');
  lines.push('');
  lines.push('## 三、测试层级与用例');
  levels.forEach(function(lv){
    var def=LEVELS[lv]||{desc:'自定义层级', sample:function(f){return '针对「'+f+'」设计该层级用例';}};
    lines.push('### '+lv);
    lines.push('- 说明：'+def.desc);
    lines.push('- 示例用例：'+def.sample(feature));
    cases++;
    lines.push('');
  });
  lines.push('## 四、测试环境');
  lines.push('- '+env);
  lines.push('');
  var risks=['依赖服务不稳定导致用例偶发失败','测试数据构造耗时，建议预置基线数据','边界组合爆炸，优先覆盖高风险路径'];
  lines.push('## 五、风险与对策');
  risks.forEach(function(r){ lines.push('- '+r); });
  lines.push('');
  lines.push('## 六、出口准则');
  lines.push('- 计划内用例 100% 执行，无遗留 P0 / P1 缺陷');
  lines.push('- 关键路径自动化用例通过率不低于约定阈值');
  return {title:feature+' 测试计划', levelCount:levels.length, caseCount:cases, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, buildTestPlan:buildTestPlan};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TestPlanForgePure = EXPORTS; }
